// Select this week's featured prediction
// Rotate through the top predictions by week number
const items = $input.all();
const preds = items[0].json.predictions ?? [];
const weekNum = Math.floor(Date.now() / (7 * 24 * 3600 * 1000));
const featured = preds[weekNum % preds.length] ?? preds[0];

return [{
  json: {
    pollId: featured.id,
    question: featured.poll_question,
    options: featured.poll_options,
    basis: featured.basis,
    confidence: featured.confidence,
    tier: featured.confidence_tier,
    pollUrl: `https://gtavi.ai/community/polls/${featured.id}`,
    embedUrl: `https://gtavi.ai/community/polls/embed/${featured.id}`,
    ogImageUrl: `https://gtavi.ai/og/poll/${featured.id}.png`,
  }
}];

values.content:
Write 3 post variants for this poll:

Question: {{ $json.question }}
Options: {{ $json.options.join(' / ') }}
Basis: {{ $json.basis.slice(0, 300) }}
Confidence: {{ $json.confidence }}% ({{ $json.tier }})
Poll URL: {{ $json.pollUrl }}

Variant 1: X/Twitter (max 240 chars, punchy, question format, ends with URL)
Variant 2: Reddit title + 3-line body (analytical tone, cite the confidence score, invite debate)
Variant 3: Discord announcement (1 paragraph, bold the question, include embed URL)

Return as JSON: { x: string, reddit: { title: string, body: string }, discord: string }

parameters.jsCode:
// Parse Claude's JSON response
const raw = $input.first().json.text ?? $input.first().json.content ?? '';
let parsed;
try {
  const jsonMatch = raw.match(/\{[\s\S]+\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : raw);
} catch {
  parsed = { x: raw.slice(0, 240), reddit: { title: 'GTA VI Poll', body: raw.slice(0, 300) }, discord: raw.slice(0, 500) };
}
const featured = $('Select Featured Poll').first().json;
return [{ json: { ...featured, copy: parsed } }];
